use crate::db::Database;
use crate::models::{Story, StoryVersion};
use crate::repositories::{StoryRepository, StorySnapshotRepository, StoryVersionRepository};

/// Create a new story version with an initial snapshot containing the provided content.
/// Updates the story's active pointers to the new version/snapshot.
pub fn create_story_version(
    db: &Database,
    story_id: &str,
    name: &str,
    content: &str,
) -> Result<StoryVersion, String> {
    let version = StoryVersionRepository::create(db, story_id, name).map_err(|e| e.to_string())?;

    let snapshot =
        StorySnapshotRepository::create(db, &version.id, content).map_err(|e| e.to_string())?;

    StoryRepository::set_active_version(db, story_id, &version.id).map_err(|e| e.to_string())?;
    StoryRepository::set_active_snapshot(db, story_id, &snapshot.id).map_err(|e| e.to_string())?;

    Ok(version)
}

/// Delete a story version. Prevents deletion of the last version.
/// If deleting the active version, auto-switches to another version first.
pub fn delete_story_version(db: &Database, version_id: &str) -> Result<(), String> {
    let version = StoryVersionRepository::get(db, version_id)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "Version not found".to_string())?;

    let story_id = version.story_id.clone();

    let version_count =
        StoryVersionRepository::count_by_story(db, &story_id).map_err(|e| e.to_string())?;

    if version_count <= 1 {
        return Err("Cannot delete the last version of a story".to_string());
    }

    let story = StoryRepository::find_by_id(db, &story_id).map_err(|e| e.to_string())?;
    let is_active_version = story.active_version_id.as_ref() == Some(&version_id.to_string());

    if is_active_version {
        let all_versions =
            StoryVersionRepository::list_by_story(db, &story_id).map_err(|e| e.to_string())?;

        let new_active = all_versions
            .iter()
            .filter(|v| v.id != version_id)
            .last()
            .ok_or_else(|| "No other version to switch to".to_string())?;

        StoryRepository::set_active_version(db, &story_id, &new_active.id)
            .map_err(|e| e.to_string())?;

        if let Some(latest_snapshot) =
            StorySnapshotRepository::get_latest(db, &new_active.id).map_err(|e| e.to_string())?
        {
            StoryRepository::set_active_snapshot(db, &story_id, &latest_snapshot.id)
                .map_err(|e| e.to_string())?;
        } else {
            db.execute(
                "UPDATE stories SET active_snapshot_id = NULL WHERE id = ?1",
                rusqlite::params![&story_id],
            )
            .map_err(|e| e.to_string())?;
        }
    }

    StoryVersionRepository::delete(db, version_id).map_err(|e| e.to_string())?;

    Ok(())
}

/// Switch the active version for a story.
/// Updates both active_version_id and active_snapshot_id (to latest snapshot of new version).
pub fn switch_story_version(
    db: &Database,
    story_id: &str,
    version_id: &str,
) -> Result<Story, String> {
    let version = StoryVersionRepository::get(db, version_id)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "Version not found".to_string())?;

    if version.story_id != story_id {
        return Err("Version does not belong to this story".to_string());
    }

    StoryRepository::set_active_version(db, story_id, version_id).map_err(|e| e.to_string())?;

    let latest_snapshot = StorySnapshotRepository::get_latest(db, version_id)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| "No snapshots found for version".to_string())?;

    StoryRepository::set_active_snapshot(db, story_id, &latest_snapshot.id)
        .map_err(|e| e.to_string())?;

    StoryRepository::find_by_id(db, story_id).map_err(|e| e.to_string())
}

/// File naming utilities for story children
///
/// This module provides functions to generate consistent, filesystem-safe
/// filenames for child stories (chapters, scenes, etc.) in Git repositories.
/// Files are named with an order prefix and slugified title: "001-chapter-name.md"
use deunicode::deunicode;
/// Slugify a string to make it filesystem and URL-safe
///
/// Transliterates Unicode characters to ASCII equivalents (e.g., é→e, ü→u),
/// converts to lowercase, replaces spaces with hyphens, removes invalid characters
///
/// # Arguments
/// * `text` - The text to slugify
///
/// # Returns
/// A slugified string safe for use in filenames
///
/// # Examples
/// * "Café Résumé" → "cafe-resume"
/// * "Müller" → "muller"
/// * "José García" → "jose-garcia"
#[allow(dead_code)]
pub fn slugify(text: &str) -> String {
    // First transliterate Unicode to ASCII
    let transliterated = deunicode(text);

    transliterated
        .to_lowercase()
        .trim()
        // Replace spaces and underscores with hyphens
        .replace(|c: char| c.is_whitespace() || c == '_', "-")
        // Remove any character that's not ASCII alphanumeric or hyphen
        .chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '-')
        .collect::<String>()
        // Replace multiple consecutive hyphens with single hyphen
        .split('-')
        .filter(|s| !s.is_empty())
        .collect::<Vec<&str>>()
        .join("-")
}

/// Slugify a variation name to create a Git branch name
///
/// This is an enhanced version of slugify specifically for variation names.
/// It converts display names like "What if Sarah lived?" to branch-safe names
/// like "what-if-sarah-lived".
///
/// # Rules:
/// - Convert to lowercase
/// - Replace spaces with hyphens
/// - Remove special characters (keep only alphanumeric and hyphens)
/// - Collapse multiple consecutive hyphens into one
/// - Trim hyphens from start and end
/// - If result is empty or all-special-chars, return "untitled"
/// - Truncate to 63 characters max (Git ref component limit)
///
/// # Arguments
/// * `name` - The variation display name
///
/// # Returns
/// A slugified branch name, or "untitled" if the input is empty or contains only special chars
#[allow(dead_code)]
pub fn slugify_variation_name(name: &str) -> String {
    // Use the existing slugify logic
    let slug = slugify(name);

    // Handle empty results
    if slug.is_empty() {
        return "untitled".to_string();
    }

    // Truncate to 63 characters (Git ref component limit)
    if slug.len() > 63 {
        // Try to truncate at a hyphen boundary to avoid cutting words
        if let Some(pos) = slug[..63].rfind('-') {
            slug[..pos].to_string()
        } else {
            slug[..63].to_string()
        }
    } else {
        slug
    }
}

/// Create a unique slugified variation name by checking against existing branch names
///
/// If the slugified name already exists as a branch, appends -2, -3, etc.
/// until a unique name is found. If more than 1000 duplicates exist (extremely rare),
/// appends a UUID suffix to guarantee uniqueness.
///
/// # Arguments
/// * `name` - The variation display name
/// * `existing_branches` - List of existing branch names
///
/// # Returns
/// A unique slugified branch name that doesn't conflict with existing branches
///
/// # Examples
/// ```ignore
/// let branches = vec!["main".to_string(), "what-if-sarah-lived".to_string()];
/// let unique = slugify_unique_variation("What if Sarah lived?", &branches);
/// // Returns "what-if-sarah-lived-2"
/// ```
#[allow(dead_code)]
pub fn slugify_unique_variation(name: &str, existing_branches: &[String]) -> String {
    let base_slug = slugify_variation_name(name);

    // If no collision, return the base slug
    if !existing_branches.contains(&base_slug) {
        return base_slug;
    }

    // If there's a collision, append a counter
    let mut counter = 2;
    loop {
        let unique_slug = format!("{base_slug}-{counter}");
        if !existing_branches.contains(&unique_slug) {
            return unique_slug;
        }
        counter += 1;

        // Safety: prevent infinite loop with UUID suffix for guaranteed uniqueness
        if counter > 1000 {
            let uuid_suffix = uuid::Uuid::new_v4().to_string()[..8].to_string();
            return format!("{base_slug}-{uuid_suffix}");
        }
    }
}

/// Generate a filename for a child story
///
/// Creates a filename with format: "{order:03}-{slugified-title}.md"
/// For example: "001-first-chapter.md", "042-the-final-battle.md"
///
/// # Arguments
/// * `order` - The order/position of the story (1-based)
/// * `title` - The title of the story
///
/// # Returns
/// A formatted filename string
#[allow(dead_code)]
pub fn generate_filename(order: usize, title: &str) -> String {
    let slug = slugify(title);

    // If slug is empty (e.g., title was all special chars), use default
    let slug = if slug.is_empty() {
        "untitled".to_string()
    } else {
        slug
    };

    format!("{order:03}-{slug}.md")
}

/// Generate a unique filename by appending a counter if needed
///
/// If the generated filename already exists in the provided list,
/// appends a counter: "001-chapter-2.md", "001-chapter-3.md", etc.
/// If more than 1000 duplicates exist (extremely rare), appends a UUID
/// suffix to guarantee uniqueness.
///
/// # Arguments
/// * `order` - The order/position of the story (1-based)
/// * `title` - The title of the story
/// * `existing_filenames` - List of filenames that already exist
///
/// # Returns
/// A unique filename that doesn't exist in the provided list
#[allow(dead_code)]
pub fn generate_unique_filename(
    order: usize,
    title: &str,
    existing_filenames: &[String],
) -> String {
    let base_filename = generate_filename(order, title);

    // If no collision, return the base filename
    if !existing_filenames.contains(&base_filename) {
        return base_filename;
    }

    // If there's a collision, append a counter
    let slug = slugify(title);
    let slug = if slug.is_empty() {
        "untitled".to_string()
    } else {
        slug
    };

    let mut counter = 2;
    loop {
        let filename = format!("{order:03}-{slug}-{counter}.md");
        if !existing_filenames.contains(&filename) {
            return filename;
        }
        counter += 1;

        // Safety: prevent infinite loop with UUID suffix for guaranteed uniqueness
        if counter > 1000 {
            let uuid_suffix = uuid::Uuid::new_v4().to_string()[..8].to_string();
            return format!("{order:03}-{slug}-{uuid_suffix}.md");
        }
    }
}

