use rusqlite::{Connection, Result};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

/// Database connection wrapper
pub struct Database {
    conn: Arc<Mutex<Connection>>,
}

impl Database {
    /// Create a new database connection
    pub fn new(db_path: PathBuf) -> Result<Self> {
        // Ensure parent directory exists
        if let Some(parent) = db_path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| {
                rusqlite::Error::InvalidPath(PathBuf::from(format!(
                    "Failed to create database directory: {e}"
                )))
            })?;
        }

        let conn = Connection::open(&db_path)?;

        // Enable foreign keys (this pragma doesn't return results)
        conn.execute("PRAGMA foreign_keys = ON", [])?;

        // Enable WAL mode for better concurrency (use pragma_update since it returns a value)
        conn.pragma_update(None, "journal_mode", "WAL")?;

        Ok(Self {
            conn: Arc::new(Mutex::new(conn)),
        })
    }

    /// Get a reference to the connection
    pub fn connection(&self) -> Arc<Mutex<Connection>> {
        Arc::clone(&self.conn)
    }

    /// Execute a query that doesn't return rows
    pub fn execute(&self, sql: &str, params: &[&dyn rusqlite::ToSql]) -> Result<usize> {
        let conn = self.conn.lock().unwrap();
        conn.execute(sql, params)
    }

    /// Execute a query and process results
    #[allow(dead_code)]
    pub fn query<T, F>(&self, sql: &str, params: &[&dyn rusqlite::ToSql], f: F) -> Result<Vec<T>>
    where
        F: FnMut(&rusqlite::Row) -> Result<T>,
    {
        let conn = self.conn.lock().unwrap();
        let mut stmt = conn.prepare(sql)?;
        let rows = stmt.query_map(params, f)?;
        rows.collect()
    }

    /// Execute a query and return a single optional result
    #[allow(dead_code)]
    pub fn query_one<T, F>(
        &self,
        sql: &str,
        params: &[&dyn rusqlite::ToSql],
        f: F,
    ) -> Result<Option<T>>
    where
        F: FnOnce(&rusqlite::Row) -> Result<T>,
    {
        let conn = self.conn.lock().unwrap();
        let mut stmt = conn.prepare(sql)?;
        let mut rows = stmt.query(params)?;

        if let Some(row) = rows.next()? {
            Ok(Some(f(row)?))
        } else {
            Ok(None)
        }
    }
}

use rusqlite::{params, Connection, Result};
use uuid::Uuid;

/// Current database schema version
#[allow(dead_code)]
const SCHEMA_VERSION: i32 = 2;

/// Run all database migrations
pub fn run_migrations(conn: &Connection) -> Result<()> {
    // Create schema_version table if it doesn't exist
    conn.execute(
        "CREATE TABLE IF NOT EXISTS schema_version (
            version INTEGER PRIMARY KEY,
            applied_at TEXT NOT NULL DEFAULT (datetime('now'))
        )",
        [],
    )?;

    // Get current version
    let current_version: i32 = conn
        .query_row(
            "SELECT COALESCE(MAX(version), 0) FROM schema_version",
            [],
            |row| row.get(0),
        )
        .unwrap_or(0);

    // Apply migrations sequentially
    if current_version < 1 {
        migrate_v1(conn)?;
        conn.execute("INSERT INTO schema_version (version) VALUES (1)", [])?;
    }

    if current_version < 2 {
        migrate_v2(conn)?;
        conn.execute("INSERT INTO schema_version (version) VALUES (2)", [])?;
    }

    Ok(())
}

/// Initial schema - Version 1
/// Creates tables for Universe and Element domain models
/// NOTE: Stories table removed - will be recreated in container/story refactor
fn migrate_v1(conn: &Connection) -> Result<()> {
    // Universes table
    conn.execute(
        "CREATE TABLE IF NOT EXISTS universes (
            id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            description TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            genre TEXT,
            tone TEXT,
            worldbuilding_notes TEXT,
            themes TEXT, -- JSON array
            status TEXT NOT NULL,
            color TEXT,
            icon TEXT,
            tags TEXT -- JSON array
        )",
        [],
    )?;

    // Containers table
    conn.execute(
        "CREATE TABLE IF NOT EXISTS containers (
            id TEXT PRIMARY KEY,
            universe_id TEXT NOT NULL,
            parent_container_id TEXT,
            container_type TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT,
            \"order\" INTEGER,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (universe_id) REFERENCES universes(id) ON DELETE CASCADE,
            FOREIGN KEY (parent_container_id) REFERENCES containers(id) ON DELETE CASCADE
        )",
        [],
    )?;

    // Stories table - Content-only model with database versioning
    conn.execute(
        "CREATE TABLE IF NOT EXISTS stories (
            id TEXT PRIMARY KEY,
            universe_id TEXT NOT NULL,
            container_id TEXT,
            story_type TEXT NOT NULL DEFAULT 'chapter',
            status TEXT NOT NULL DEFAULT 'draft',
            title TEXT NOT NULL,
            description TEXT NOT NULL DEFAULT '',
            word_count INTEGER NOT NULL DEFAULT 0,
            target_word_count INTEGER,
            notes TEXT,
            outline TEXT,
            \"order\" INTEGER,
            tags TEXT,  -- JSON array
            color TEXT,
            favorite INTEGER DEFAULT 0,
            related_element_ids TEXT,  -- JSON array
            series_name TEXT,
            last_edited_at TEXT NOT NULL,
            version INTEGER NOT NULL DEFAULT 1,
            variation_group_id TEXT NOT NULL,
            variation_type TEXT NOT NULL DEFAULT 'original',
            parent_variation_id TEXT,
            active_version_id TEXT,
            active_snapshot_id TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (universe_id) REFERENCES universes(id) ON DELETE CASCADE,
            FOREIGN KEY (container_id) REFERENCES containers(id) ON DELETE CASCADE,
            FOREIGN KEY (active_version_id) REFERENCES story_versions(id),
            FOREIGN KEY (active_snapshot_id) REFERENCES story_snapshots(id)
        )",
        [],
    )?;

    // Elements table
    conn.execute(
        "CREATE TABLE IF NOT EXISTS elements (
            id TEXT PRIMARY KEY,
            universe_id TEXT NOT NULL,
            name TEXT NOT NULL,
            description TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
